INSERT INTO dbo.reportdata (code1, value1) SELECT sl.saleinvcode AS invcode, (CASE WHEN (round((sum(((((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - (sd.discperc / 100)))) * ((1 - (sl.discperc / 100)))) - flatdisc) + misccharges)))::numeric, 2) IS NULL) THEN 0 ELSE round((((sum(((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - (sd.discperc / 100)))) * ((1 - (sl.discperc / 100))))) - flatdisc) + misccharges))::numeric, 0) END + round(((sum(round((((((sd.looseqty + sd.bonusqty)) * sd.unitsalestax) + round((((round((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc))) * ((1 - (sd.discperc * 0.01)))))::numeric, 2) * sd.gstperc) * 0.01))::numeric, 2)))::numeric, 2)) + (CASE WHEN ((((round((sum((((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - (sd.discperc / 100)))) * ((1 - (sl.discperc / 100)))) - flatdisc)))::numeric, 2)) * sl.invgstperc1) * 0.01) IS NULL) THEN 0 ELSE (((round(((sum(((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - (sd.discperc / 100)))) * ((1 - (sl.discperc / 100))))) - flatdisc))::numeric, 2)) * sl.invgstperc1) * 0.01) END)))::numeric, 0)) AS netamount FROM dbo.saleledger AS sl, dbo.saledetail AS sd WHERE ((sl.saleinvcode = sd.saleinvcode)) GROUP BY sl.saleinvcode, sl.flatdisc, sl.misccharges, sl.discperc, sl.invgstperc1;
