UPDATE dbo.prledger SET invtotal = pr.nettotal FROM (SELECT prledger.prinvcode AS prinvcode, (round((((sum((((prdetail.looseqty + prdetail.bonusqty)) * prdetail.unitsalestax)) + sum(round((((((prdetail.looseqty * prdetail.prprice) * ((1 - ((.01 * prdetail.discperc))))) * prdetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((prdetail.looseqty * prdetail.prprice)) * ((1 - ((.01 * prdetail.discperc)))))) * ((1 - ((.01 * prledger.discperc))))) - prledger.flatdisc)) * ((prledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum((((prdetail.looseqty * prdetail.prprice)) * ((1 - ((.01 * prdetail.discperc)))))) * ((1 - ((.01 * prledger.discperc))))) + prledger.misccharges) + prledger.salestax) - prledger.flatdisc))::numeric, 0)) AS nettotal FROM dbo.prledger, dbo.prdetail WHERE (prledger.prinvcode = prdetail.prinvcode) GROUP BY prledger.prinvcode, prledger.suppcode, prledger.prcatcode, prledger.date, prledger.discperc, prledger.misccharges, prledger.salestax, prledger.flatdisc, prledger.invgstperc1) AS pr WHERE (prledger.prinvcode = pr.prinvcode);
