UPDATE dbo.purledger SET invtotal = p.net FROM (SELECT purledger.purinvcode AS purinvcode, (round((((sum(((((purdetail.looseqty + purdetail.packqty) + purdetail.bonusqty)) * purdetail.unitsalestax)) + sum(round((((((((purdetail.looseqty + purdetail.packqty)) * purdetail.purprice) * ((1 - ((.01 * purdetail.discperc))))) * purdetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((((purdetail.looseqty + purdetail.packqty)) * purdetail.purprice)) * ((1 - ((.01 * purdetail.discperc)))))) * ((1 - ((.01 * purledger.discperc))))) - purledger.flatdisc)) * ((purledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum(((((purdetail.looseqty + purdetail.packqty)) * purdetail.purprice) * ((1 - ((.01 * purdetail.discperc)))))) * ((1 - ((.01 * purledger.discperc))))) + purledger.misccharges) + purledger.salestax) - purledger.flatdisc))::numeric, 0)) AS net FROM dbo.purledger, dbo.purdetail WHERE (purledger.purinvcode = purdetail.purinvcode) GROUP BY purledger.purinvcode, purledger.suppcode, purledger.purcatcode, purledger.postdate, purledger.discperc, purledger.misccharges, purledger.salestax, purledger.flatdisc, purledger.invgstperc1) AS p WHERE (purledger.purinvcode = p.purinvcode);
