UPDATE dbo.srledger AS srledger SET invtotal = a.invtotal FROM (SELECT srledger.srinvcode AS srinvcode, (round((((sum((((srdetail.looseqty + srdetail.bonusqty)) * srdetail.unitsalestax)) + sum(round(((((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc))))) * srdetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc)))))) * ((1 - ((.01 * srledger.discperc))))) - srledger.flatdisc)) * ((srledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc)))))) * ((1 - ((.01 * srledger.discperc))))) + srledger.misccharges) + srledger.salestax) - srledger.flatdisc))::numeric, 0)) AS invtotal FROM dbo.srledger, dbo.srdetail WHERE ((srledger.srinvcode = srdetail.srinvcode) AND (srledger.posted = 'Y')) GROUP BY srledger.srinvcode, srledger.custcode, srledger.srcatcode, srledger.date, srledger.discperc, srledger.misccharges, srledger.salestax, srledger.flatdisc, srledger.invgstperc1, srledger.salesmancode, srledger.saleinvcode) AS a WHERE (srledger.srinvcode = a.srinvcode);
