INSERT INTO dbo.prodbuffer (prodcode, prodrowid, icode, qty, remarks, packunits, packprice, price, itemflatdisc, discperc, processcharge, processchargeperc) SELECT DISTINCT h.prodcode AS prodcode, d.rowid AS prodrowid, rd.icode, rd.qty, rd.remarks, rd.packunits, rd.packprice, rd.price, rd.itemflatdisc, rd.discperc, rd.processcharge, rd.processchargeperc FROM dbo.prodheader AS h, dbo.proddetail AS d, dbo.recipedetail AS rd, (SELECT r1.* FROM dbo.recipe AS r1 WHERE (((dbo.tsql_str((r1.resulteditem)::numeric, 7) || dbo.tsql_str((r1.priority)::numeric, 7)))::citext IN (SELECT DISTINCT (dbo.tsql_str((rr.resulteditem)::numeric, 7) || dbo.tsql_str((min(rr.priority))::numeric, 7)) FROM dbo.recipe AS rr WHERE (rr.resulteditem IN (SELECT DISTINCT pd.icode FROM dbo.prodheader AS p, dbo.proddetail AS pd WHERE ((p.finalized = 'Y') AND (p.prodcode = pd.prodcode)))) GROUP BY rr.resulteditem))) AS r WHERE ((((h.finalized = 'Y') AND (h.prodcode = d.prodcode)) AND (d.icode = r.resulteditem)) AND (r.recipecode = rd.recipecode));
